  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52", "C21", "C23", "C56", "C01"],
      "claim": "Several transferred molecules have absolute oral bioavailability values well above 20% in healthy volunteers or humans, including 77% fed, 57% fasted, 70%, ~50%, and ~100%."
    },
    {
      "card_ids": ["C18", "C55", "C47"],
      "claim": "Linezolid is consistently reported with ~100% absolute oral bioavailability in humans, strongly supporting the high category."
    },
    {
      "card_ids": ["C08", "C48", "C46"],
      "claim": "Paliperidone extended-release formulations have 28% absolute oral bioavailability in healthy volunteers or humans, above the 20% threshold."
    },
    {
      "card_ids": ["C07", "C27", "C38", "C49", "C02"],
      "claim": "Encainide mean or absolute bioavailability values are mostly 20-78% across healthy subjects and patients, with higher values in cirrhosis; a qualitative low report and a wide range introduce uncertainty but do not overturn the high direction."
    },
    {
      "card_ids": ["C39", "C31"],
      "claim": "Borderline-threshold transferred molecules also support high: tacrolimus ~20-25% and praziquantel 27.2±5.4%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C11", "C44"],
  "decision_summary": "All transferred evidence with numeric absolute oral bioavailability is at or above 20% (mostly 28-100%); the only below-threshold signals are a qualitative low encainide report and the lower end of its wide range, so the best-supported prediction is high.",
  "evidence_gaps": [
    "Encainide has a qualitative 'low' report and a bioavailability range extending to 7%, so some subpopulations may fall below 20%.",
    "Some records are from altered conditions (cirrhosis, fed/fasted) or use unspecified bioavailability type, but their numeric values remain above the threshold."
